import {rational} from './b16-model.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(action,label,index,pressed=false)=>`<button type="button" data-x="r38-${action}"${index===undefined?'':` data-index="${esc(index)}"`} aria-pressed="${!!pressed}">${esc(label)}</button>`;
const inp=(k,label,v)=>`<label class="r38-field">${esc(label)}<input data-xfield="${k}" value="${esc(v)}" autocomplete="off" maxlength="120"></label>`;
const labels={less:'更小',equal:'一样大',greater:'更大'};
function triangle(){return `<svg class="r38-triangle" viewBox="0 0 300 225" role="img" aria-label="一个三角形，已知两角为50度和70度，第三个角未知"><path d="M40 200 L240 200 L179.5 33.7 Z" fill="#e0ede1" stroke="#587e6d" stroke-width="3"/><text x="53" y="189">50°</text><text x="206" y="189">70°</text><text x="165" y="75">？</text></svg>`;}
function exchange(b){const tens=b.exchanged?6:7,ones=b.exchanged?11:1;return `<div class="r38-place"><div><b>十位</b><span>${Array.from({length:tens},()=>'<i class="r38-ten"></i>').join('')}</span></div><div><b>个位</b><span>${Array.from({length:ones},()=>'<i class="r38-one"></i>').join('')}</span></div></div>${btn('exchange',b.exchanged?'把十个一换回一捆':'拆开一捆十')}`;}
function array(b){return `<p>每一列都是6个点，点两列把它们拿走。</p><div class="r38-array">${Array.from({length:10},(_,i)=>`<button type="button" data-x="r38-column" data-index="${i}" aria-pressed="${b.removed.includes(i)}" aria-label="第${i+1}列，${b.removed.includes(i)?'已拿走':'保留'}">${Array.from({length:6},()=>'<i></i>').join('')}</button>`).join('')}</div><p>已拿走 ${b.removed.length} 列。</p>`;}
function chain(t,m){const b=m.board;return `${t.scene==='triangle'?triangle():t.scene==='exchange'?exchange(b):t.scene==='array'?array(b):''}${t.sceneText?`<p class="r38-scene">${esc(t.sceneText)}</p>`:''}${t.lines?`<div class="r38-lines"><strong>有人这样想：</strong>${t.lines.map(l=>btn('mark',l.text,l.id,b.marked===l.id)).join('')}<small>点出你认为最先出错的一步。</small></div>`:''}<div class="r38-chain"><strong>我的思路</strong>${b.selected.length?b.selected.map((id,i)=>`<div><span>${i+1}</span>${esc(t.cards.find(c=>c.id===id)?.text)}</div>`).join(''):'<p>还没有放入步骤</p>'}</div>`;}
function values(s){const r=rational(String(s));return r&&r[1]!==0?r[0]/r[1]:NaN;}
function counter(m){const last=m.board.records.at(-1);if(!last)return '<div class="r38-empty">先猜一猜，再让两个量出现在这里。</div>';if(last.value!==m.value||last.factor!==m.second||last.prediction!==m.choice)return '<div class="r38-empty">你改了数字或猜测，试一次再比较。</div>';const a=values(last.value),p=a*values(last.factor),max=Math.max(a,p),x=rational(last.value),y=rational(last.factor);let n=BigInt(x[0])*BigInt(y[0]),d=BigInt(x[1])*BigInt(y[1]),u=n<0n?-n:n,v=d;while(v)[u,v]=[v,u%v];n/=u||1n;d/=u||1n;const exact=d===1n?String(n):`${n}/${d}`;return `<div class="r38-bars"><div><span>原来的数</span><i><b style="width:${a/max*100}%"></b></i><strong>${esc(last.value)}</strong></div><div><span>乘完以后</span><i><b style="width:${p/max*100}%"></b></i><strong>${esc(exact)}</strong></div></div><p>${esc(last.value)} × ${esc(last.factor)}，结果${labels[last.actual]}。${last.breaks?'这次和那句话对不上。':'这次还没有推翻那句话，可以换个数。'}</p>`;}
export function visual(t,m){return `<div class="r38-world">${t.type==='x-r38-chain'?chain(t,m):counter(m)}</div>`;}
export function controls(t,m){let out='<div class="r38-controls">';if(t.type==='x-r38-chain'){out+=`<div class="r38-cards">${t.cards.filter(c=>!m.board.selected.includes(c.id)).map(c=>btn('card',c.text,c.id)).join('')}</div>${btn('undo','撤回上一步')}`;}else{out+=inp('value','原来的数（大于0，最多12）',m.value)+inp('second','乘多少（0到3，可写1/2）',m.second)+`<label class="r38-field">先猜结果<select data-xfield="choice"><option value="">选择</option>${Object.entries(labels).map(([v,l])=>`<option value="${v}" ${v===m.choice?'selected':''}>${l}</option>`).join('')}</select></label>`+btn('test','试一试');}if(m.issue)out+=`<p class="r38-issue" role="status">${esc(m.issue)}</p>`;return out+`<details><summary>留下自己的想法（可选）</summary><label class="r38-field">我的解释或新问题<textarea data-xfield="prose" maxlength="2000">${esc(m.prose)}</textarea></label><small>原话会保存，暂不自动判断。</small></details></div>`;}
export const render=(t,m)=>`<div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div>`;
